lib/pyth-sdk-solidity/PythStructs.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

/**
 * @notice **Deprecated** – this codebase will be removed on **1 August 2025**.
 *
 * @dev    Switch to the maintained package:
 * See Pyth Network documentation for details.
 *
 *         Migration guide:
 *         https://docs.pyth.network/price-feeds/use-real-time-data/evm
 *
 * @custom:deprecated Repository scheduled for deletion on 1 August 2025.
 * See Pyth Network documentation for details.
 */
contract PythStructs {
    // A price with a degree of uncertainty, represented as a price +- a confidence interval.
    //
    // The confidence interval roughly corresponds to the standard error of a normal distribution.
    // Both the price and confidence are stored in a fixed-point numeric representation,
    // `x * (10^expo)`, where `expo` is the exponent.
    //
    // Please refer to the documentation at https://docs.pyth.network/consumers/best-practices for how
    // to how this price safely.
    struct Price {
        // Price
        int64 price;
        // Confidence interval around the price
        uint64 conf;
        // Price exponent
        int32 expo;
        // Unix timestamp describing when the price was published
        uint publishTime;
    }

    // PriceFeed represents a current aggregate price from pyth publisher feeds.
    struct PriceFeed {
        // The price ID.
        bytes32 id;
        // Latest available price
        Price price;
        // Latest available exponentially-weighted moving average price
        Price emaPrice;
    }
}

src/ActivityLog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title ActivityLog
 * @author Arbit Protocol
 * @notice Every action an agent takes under Arbit is written here permanently.
 *         Think of it as the agent's black box — an append-only record that
 *         nobody can alter, not even the protocol itself.
 *
 * @dev The tamper-proof guarantee comes from two mechanisms working together:
 *      1. No delete or update functions exist anywhere in this contract.
 *         You cannot remove what has been written. The ABI does not allow it.
 *      2. Every entry hashes the previous entry's hash into itself, creating
 *         a cryptographic chain. Altering any past entry breaks every hash
 *         that follows it — making silent tampering mathematically impossible.
 *
 * @dev Security invariants:
 *      1. entryCount only ever increases — never decreases
 *      2. latestHash always reflects the most recent entry
 *      3. Only the authorised writer address can add entries
 *      4. The writer address can only be set once and never changed
 *
 * @custom:security-contact security@arbitprotocol.xyz
 */
contract ActivityLog {

    // -------------------------------------------------------------------------
    // Custom errors
    // -------------------------------------------------------------------------

    error ZeroAddressNotAllowed();
    error WriterAlreadySet();
    error OnlyWriterCanDoThis(address caller, address writer);
    error EntryDoesNotExist(uint256 index, uint256 totalEntries);
    error EmptyReasonNotAllowed();

    // -------------------------------------------------------------------------
    // Action type constants — must stay in sync with PolicyRegistry
    // -------------------------------------------------------------------------

    uint8 public constant ACTION_DATA_FEED   = 0;
    uint8 public constant ACTION_DEX_SWAP    = 1;
    uint8 public constant ACTION_LENDING     = 2;
    uint8 public constant ACTION_MARKETPLACE = 3;
    uint8 public constant ACTION_YIELD       = 4;

    // Log entry types that go beyond normal agent actions
    uint8 public constant LOG_PAYMENT_EXECUTED  = 10;
    uint8 public constant LOG_PAYMENT_BLOCKED   = 11;
    uint8 public constant LOG_RISK_RESUME       = 12;
    uint8 public constant LOG_POLICY_REVOKED    = 13;
    uint8 public constant LOG_AGENT_HIRED       = 14;
    uint8 public constant LOG_STAKE_SLASHED     = 15;

    // -------------------------------------------------------------------------
    // The log entry structure
    // -------------------------------------------------------------------------

    /**
     * @dev Each entry captures the full context of what happened, why it
     *      happened, and where it fits in the chain of all past entries.
     *      Nothing here can be changed after it is written.
     */
    struct LogEntry {
        // Which policy was active when this action occurred
        bytes32 policyId;

        // The agent wallet that took the action
        address agent;

        // What kind of action this was — use the constants above
        uint8 actionType;

        // How much USDC moved (or was blocked from moving)
        uint256 amount;

        // The risk score at the exact moment this entry was written
        uint8 riskScoreAtTime;

        // A short human-readable reason — required for blocked payments
        bytes32 reason;

        // When this happened
        uint256 timestamp;

        // The hash of the entry before this one in the chain
        // Entry 0 uses bytes32(0) as its predecessor
        bytes32 previousEntryHash;

        // The hash of this entry itself — computed at write time
        // and stored so anyone can verify the chain without recomputing
        bytes32 entryHash;
    }

    // -------------------------------------------------------------------------
    // Storage
    // -------------------------------------------------------------------------

    // The canonical ordered list of all log entries ever written
    LogEntry[] private entries;

    // The hash of the most recently written entry
    // Always updated atomically with the entry write
    bytes32 public latestHash;

    // Total number of entries written — only ever increases
    uint256 public entryCount;

    // The only address permitted to write entries
    // Set once at deployment, never changeable
    address public writer;
    bool    private writerSet;

    // Per-policy index for efficient lookup of an agent's history
    // Maps policyId => array of entry indices in the main entries array
    mapping(bytes32 => uint256[]) private policyEntryIndices;

    // Per-agent index for the same reason
    mapping(address => uint256[]) private agentEntryIndices;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event EntryWritten(
        uint256 indexed entryIndex,
        bytes32 indexed policyId,
        address indexed agent,
        uint8 actionType,
        uint256 amount,
        bytes32 entryHash
    );

    event WriterAuthorised(address indexed writer);

    // -------------------------------------------------------------------------
    // One-time writer setup
    // -------------------------------------------------------------------------

    /**
     * @notice Authorise the SentinelGate contract as the sole writer.
     * @dev Called once after SentinelGate is deployed. After this call
     *      the writer is permanently locked. There is no override.
     */
    function setWriter(address _writer) external {
        if (writerSet) revert WriterAlreadySet();
        if (_writer == address(0)) revert ZeroAddressNotAllowed();
        writer = _writer;
        writerSet = true;
        emit WriterAuthorised(_writer);
    }

    modifier onlyWriter() {
        if (msg.sender != writer)
            revert OnlyWriterCanDoThis(msg.sender, writer);
        _;
    }

    // -------------------------------------------------------------------------
    // Writing entries
    // -------------------------------------------------------------------------

    /**
     * @notice Write a new entry to the log.
     * @dev Only SentinelGate may call this. Every field is recorded as-is
     *      with no transformation. The cryptographic chain is maintained
     *      automatically — the caller does not need to manage it.
     *
     * @param policyId       The active policy at time of action.
     * @param agent          The agent that acted.
     * @param actionType     What kind of action occurred.
     * @param amount         How much USDC was involved.
     * @param riskScore      The RiskGuardian score at this moment.
     * @param reason         Why this happened — required for blocked entries.
     */
    function writeEntry(
        bytes32 policyId,
        address agent,
        uint8   actionType,
        uint256 amount,
        uint8   riskScore,
        bytes32 reason
    )
        external
        onlyWriter
        returns (uint256 entryIndex, bytes32 entryHash)
    {
        // --- CHECKS ----------------------------------------------------------

        if (agent == address(0)) revert ZeroAddressNotAllowed();

        // Blocked payment entries must always carry a reason
        // so the audit trail explains why the payment did not go through
        if (actionType == LOG_PAYMENT_BLOCKED && reason == bytes32(0))
            revert EmptyReasonNotAllowed();

        // --- EFFECTS ---------------------------------------------------------

        entryIndex = entryCount;

        // Build the entry hash by hashing all fields together with the
        // previous entry's hash. This is what creates the cryptographic chain.
        entryHash = keccak256(abi.encodePacked(
            policyId,
            agent,
            actionType,
            amount,
            riskScore,
            reason,
            block.timestamp,
            latestHash       // previous entry's hash — links the chain
        ));

        LogEntry memory entry = LogEntry({
            policyId:          policyId,
            agent:             agent,
            actionType:        actionType,
            amount:            amount,
            riskScoreAtTime:   riskScore,
            reason:            reason,
            timestamp:         block.timestamp,
            previousEntryHash: latestHash,
            entryHash:         entryHash
        });

        // Write to storage in a single push — no partial writes possible
        entries.push(entry);

        // Update the chain tip and counter atomically
        latestHash = entryHash;
        entryCount++;

        // Update the lookup indices for efficient querying
        policyEntryIndices[policyId].push(entryIndex);
        agentEntryIndices[agent].push(entryIndex);

        emit EntryWritten(
            entryIndex,
            policyId,
            agent,
            actionType,
            amount,
            entryHash
        );
    }

    // -------------------------------------------------------------------------
    // Reading entries
    // -------------------------------------------------------------------------

    /**
     * @notice Fetch a single entry by its position in the log.
     */
    function getEntry(uint256 index)
        external
        view
        returns (LogEntry memory)
    {
        if (index >= entryCount)
            revert EntryDoesNotExist(index, entryCount);
        return entries[index];
    }

    /**
     * @notice Fetch all entry indices recorded against a specific policy.
     * @dev Returns indices into the main log — call getEntry for each one.
     */
    function getEntriesForPolicy(bytes32 policyId)
        external
        view
        returns (uint256[] memory)
    {
        return policyEntryIndices[policyId];
    }

    /**
     * @notice Fetch all entry indices recorded against a specific agent.
     */
    function getEntriesForAgent(address agent)
        external
        view
        returns (uint256[] memory)
    {
        return agentEntryIndices[agent];
    }

    /**
     * @notice Verify that the chain is intact from a given starting entry.
     * @dev Recomputes every hash from startIndex to the current tip and
     *      checks each one matches what was stored at write time.
     *      Returns true only if every link in the chain is unbroken.
     *
     *      This is the tamper-detection function. If anyone has managed to
     *      alter any entry in storage, this function will return false.
     *
     * @param startIndex  Where to begin verification (0 = from the beginning)
     * @return intact     Whether the chain is unbroken from startIndex to tip
     * @return brokenAt   The index where the first break was found (if any)
     */
    function verifyChain(uint256 startIndex)
        external
        view
        returns (bool intact, uint256 brokenAt)
    {
        if (entryCount == 0) return (true, 0);
        if (startIndex >= entryCount)
            revert EntryDoesNotExist(startIndex, entryCount);

        for (uint256 i = startIndex; i < entryCount; i++) {
            LogEntry storage entry = entries[i];

            bytes32 expected = keccak256(abi.encodePacked(
                entry.policyId,
                entry.agent,
                entry.actionType,
                entry.amount,
                entry.riskScoreAtTime,
                entry.reason,
                entry.timestamp,
                entry.previousEntryHash
            ));

            if (expected != entry.entryHash) {
                return (false, i);
            }
        }

        return (true, 0);
    }

    /**
     * @notice Get the most recent N entries across the entire log.
     * @dev Useful for the demo — shows the last few actions at a glance.
     */
    function getRecentEntries(uint256 count)
        external
        view
        returns (LogEntry[] memory recent)
    {
        if (entryCount == 0) return new LogEntry[](0);

        uint256 actualCount = count > entryCount ? entryCount : count;
        recent = new LogEntry[](actualCount);

        for (uint256 i = 0; i < actualCount; i++) {
            recent[i] = entries[entryCount - actualCount + i];
        }
    }
}

src/PolicyRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract PolicyRegistry is ReentrancyGuard {

    error ZeroAddressNotAllowed();
    error AgentCannotOwnItsPolicy();
    error BudgetCannotBeZero();
    error RiskCeilingOutOfRange(uint8 provided, uint8 maximum);
    error ExpiryMustBeInFuture(uint256 provided, uint256 current);
    error MaxTransactionExceedsBudget(uint256 maxTx, uint256 budget);
    error ScopeCannotBeEmpty();
    error TooManyActionTypes(uint256 provided, uint256 maximum);
    error PolicyDoesNotExist(bytes32 policyId);
    error PolicyAlreadyRevoked(bytes32 policyId);
    error PolicyExpired(bytes32 policyId, uint256 expiry, uint256 current);
    error PolicyNotActive(bytes32 policyId);
    error OnlyOwnerCanDoThis(address caller, address owner);
    error AgentCannotModifyOwnPolicy(address agent);
    error InsufficientBudget(uint256 requested, uint256 remaining);
    error TransactionExceedsMaxSize(uint256 amount, uint256 maxTx);
    error ActionTypeNotPermitted(bytes32 policyId, uint8 actionType);
    error NothingToWithdraw();
    error WithdrawalFailed();

    uint8 public constant ACTION_DATA_FEED   = 0;
    uint8 public constant ACTION_DEX_SWAP    = 1;
    uint8 public constant ACTION_LENDING     = 2;
    uint8 public constant ACTION_MARKETPLACE = 3;
    uint8 public constant ACTION_YIELD       = 4;
    uint8 public constant MAX_ACTION_TYPE    = 4;
    uint8  public constant MAX_RISK_CEILING     = 100;
    uint8  public constant ABSOLUTE_RISK_FLOOR  = 1;
    uint256 public constant MAX_SCOPE_ENTRIES   = 10;

    struct Policy {
        address owner;
        address agent;
        address token;
        uint256 maxBudget;
        uint256 spentAmount;
        uint256 maxTransactionSize;
        uint256 expiry;
        uint8 riskCeiling;
        bool isActive;
        uint8[] permittedActions;
    }

    mapping(bytes32 => Policy) private policies;
    mapping(address => bytes32[]) private ownerPolicies;
    mapping(address => bytes32) private agentActivePolicy;
    mapping(address => uint256) private ownerNonce;

    address public sentinelGate;
    bool    private gateSet = false;

    event PolicyRegistered(
        bytes32 indexed policyId,
        address indexed owner,
        address indexed agent,
        uint256 maxBudget,
        uint256 expiry
    );
    event PolicyRevoked(bytes32 indexed policyId, address indexed revokedBy, uint256 timestamp);
    event BudgetConsumed(bytes32 indexed policyId, address indexed agent, uint256 amount, uint256 remainingBudget);
    event PolicyBudgetIncreased(bytes32 indexed policyId, address indexed owner, uint256 addedAmount, uint256 newBudget);
    event PolicyExpiryExtended(bytes32 indexed policyId, address indexed owner, uint256 newExpiry);
    event PolicyRiskCeilingUpdated(bytes32 indexed policyId, address indexed owner, uint8 oldCeiling, uint8 newCeiling);

    function setSentinelGate(address _gate) external {
        if (gateSet) revert OnlyOwnerCanDoThis(msg.sender, sentinelGate);
        if (_gate == address(0)) revert ZeroAddressNotAllowed();
        sentinelGate = _gate;
        gateSet = true;
    }

    modifier onlySentinelGate() {
        if (msg.sender != sentinelGate)
            revert OnlyOwnerCanDoThis(msg.sender, sentinelGate);
        _;
    }

    function registerPolicy(
        address agent,
        address token,
        uint256 maxBudget,
        uint256 maxTransactionSize,
        uint256 expiry,
        uint8 riskCeiling,
        uint8[] calldata permittedActions
    ) external nonReentrant returns (bytes32 policyId) {
        if (agent == address(0)) revert ZeroAddressNotAllowed();
        if (token == address(0)) revert ZeroAddressNotAllowed();
        if (agent == msg.sender)  revert AgentCannotOwnItsPolicy();
        if (maxBudget == 0)       revert BudgetCannotBeZero();
        if (riskCeiling < ABSOLUTE_RISK_FLOOR || riskCeiling > MAX_RISK_CEILING)
            revert RiskCeilingOutOfRange(riskCeiling, MAX_RISK_CEILING);
        if (expiry <= block.timestamp)
            revert ExpiryMustBeInFuture(expiry, block.timestamp);
        if (maxTransactionSize > maxBudget)
            revert MaxTransactionExceedsBudget(maxTransactionSize, maxBudget);
        if (permittedActions.length == 0)
            revert ScopeCannotBeEmpty();
        if (permittedActions.length > MAX_SCOPE_ENTRIES)
            revert TooManyActionTypes(permittedActions.length, MAX_SCOPE_ENTRIES);

        for (uint256 i = 0; i < permittedActions.length; i++) {
            if (permittedActions[i] > MAX_ACTION_TYPE)
                revert ActionTypeNotPermitted(bytes32(0), permittedActions[i]);
            for (uint256 j = i + 1; j < permittedActions.length; j++) {
                if (permittedActions[i] == permittedActions[j])
                    revert ActionTypeNotPermitted(bytes32(0), permittedActions[i]);
            }
        }

        policyId = keccak256(abi.encodePacked(msg.sender, agent, ownerNonce[msg.sender]));
        ownerNonce[msg.sender]++;

        policies[policyId] = Policy({
            owner:              msg.sender,
            agent:              agent,
            token:              token,
            maxBudget:          maxBudget,
            spentAmount:        0,
            maxTransactionSize: maxTransactionSize,
            expiry:             expiry,
            riskCeiling:        riskCeiling,
            isActive:           true,
            permittedActions:   permittedActions
        });

        ownerPolicies[msg.sender].push(policyId);
        agentActivePolicy[agent] = policyId;

        emit PolicyRegistered(policyId, msg.sender, agent, maxBudget, expiry);
    }

    function consumeBudget(
        bytes32 policyId,
        uint256 amount,
        uint8 actionType
    ) external nonReentrant onlySentinelGate {
        Policy storage policy = _requireActivePolicy(policyId);

        if (amount > policy.maxTransactionSize)
            revert TransactionExceedsMaxSize(amount, policy.maxTransactionSize);

        uint256 remaining = policy.maxBudget - policy.spentAmount;
        if (amount > remaining)
            revert InsufficientBudget(amount, remaining);

        if (!_isActionPermitted(policy, actionType))
            revert ActionTypeNotPermitted(policyId, actionType);

        policy.spentAmount += amount;
        emit BudgetConsumed(policyId, policy.agent, amount, policy.maxBudget - policy.spentAmount);
    }

    function revokePolicy(bytes32 policyId) external nonReentrant {
        Policy storage policy = policies[policyId];
        if (policy.owner == address(0)) revert PolicyDoesNotExist(policyId);
        if (msg.sender != policy.owner) revert OnlyOwnerCanDoThis(msg.sender, policy.owner);
        if (!policy.isActive) revert PolicyAlreadyRevoked(policyId);

        policy.isActive = false;
        agentActivePolicy[policy.agent] = bytes32(0);
        emit PolicyRevoked(policyId, msg.sender, block.timestamp);
    }

    function increaseBudget(bytes32 policyId, uint256 additionalAmount) external nonReentrant {
        if (additionalAmount == 0) revert BudgetCannotBeZero();
        Policy storage policy = _requireOwnerAndActive(policyId);
        policy.maxBudget += additionalAmount;
        emit PolicyBudgetIncreased(policyId, msg.sender, additionalAmount, policy.maxBudget);
    }

    function extendExpiry(bytes32 policyId, uint256 newExpiry) external nonReentrant {
        Policy storage policy = _requireOwnerAndActive(policyId);
        if (newExpiry <= policy.expiry) revert ExpiryMustBeInFuture(newExpiry, policy.expiry);
        policy.expiry = newExpiry;
        emit PolicyExpiryExtended(policyId, msg.sender, newExpiry);
    }

    function updateRiskCeiling(bytes32 policyId, uint8 newCeiling) external nonReentrant {
        if (newCeiling < ABSOLUTE_RISK_FLOOR || newCeiling > MAX_RISK_CEILING)
            revert RiskCeilingOutOfRange(newCeiling, MAX_RISK_CEILING);
        Policy storage policy = _requireOwnerAndActive(policyId);
        uint8 oldCeiling = policy.riskCeiling;
        policy.riskCeiling = newCeiling;
        emit PolicyRiskCeilingUpdated(policyId, msg.sender, oldCeiling, newCeiling);
    }

    function validateAction(
        bytes32 policyId,
        uint256 amount,
        uint8 actionType
    ) external view returns (bool valid, string memory reason) {
        Policy storage policy = policies[policyId];
        if (policy.owner == address(0))      return (false, "Policy does not exist");
        if (!policy.isActive)                return (false, "Policy has been revoked");
        if (block.timestamp >= policy.expiry) return (false, "Policy has expired");
        if (amount > policy.maxTransactionSize) return (false, "Amount exceeds max transaction size");
        uint256 remaining = policy.maxBudget - policy.spentAmount;
        if (amount > remaining)              return (false, "Insufficient budget remaining");
        if (!_isActionPermitted(policy, actionType)) return (false, "Action type not permitted by this policy");
        return (true, "");
    }

    function getPolicy(bytes32 policyId) external view returns (Policy memory) {
        if (policies[policyId].owner == address(0)) revert PolicyDoesNotExist(policyId);
        return policies[policyId];
    }

    function getRemainingBudget(bytes32 policyId) external view returns (uint256) {
        Policy storage policy = policies[policyId];
        if (policy.owner == address(0)) revert PolicyDoesNotExist(policyId);
        return policy.maxBudget - policy.spentAmount;
    }

    function getActivePolicyForAgent(address agent) external view returns (bytes32) {
        return agentActivePolicy[agent];
    }

    function getPoliciesByOwner(address owner) external view returns (bytes32[] memory) {
        return ownerPolicies[owner];
    }

    function isPolicyActive(bytes32 policyId) external view returns (bool) {
        Policy storage policy = policies[policyId];
        if (policy.owner == address(0)) return false;
        return policy.isActive && block.timestamp < policy.expiry;
    }

    function _requireActivePolicy(bytes32 policyId) internal view returns (Policy storage policy) {
        policy = policies[policyId];
        if (policy.owner == address(0)) revert PolicyDoesNotExist(policyId);
        if (!policy.isActive) revert PolicyAlreadyRevoked(policyId);
        if (block.timestamp >= policy.expiry) revert PolicyExpired(policyId, policy.expiry, block.timestamp);
    }

    function _requireOwnerAndActive(bytes32 policyId) internal view returns (Policy storage policy) {
        policy = _requireActivePolicy(policyId);
        if (msg.sender != policy.owner) revert OnlyOwnerCanDoThis(msg.sender, policy.owner);
    }

    function _isActionPermitted(Policy storage policy, uint8 actionType) internal view returns (bool) {
        for (uint256 i = 0; i < policy.permittedActions.length; i++) {
            if (policy.permittedActions[i] == actionType) return true;
        }
        return false;
    }
}

src/ReputationStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title ReputationStaking
 * @author Arbit Protocol
 * @notice Agents stake USDC to list services on the Arbit marketplace.
 *         That stake is their skin in the game. Deliver good service and
 *         the stake stays intact. Behave maliciously or fail to perform
 *         and the stake gets slashed — funds go to the harmed buyer and
 *         the protocol treasury.
 *
 * @dev Security invariants:
 *      1. An agent cannot list without meeting the minimum stake
 *      2. Stake can only be withdrawn when the agent is not listed
 *      3. Only the slash authority can slash a stake
 *      4. Slashed amount never exceeds the staked amount
 *      5. Treasury address can only be set once
 *      6. Slash authority can only be set once
 *
 * @custom:security-contact security@arbitprotocol.xyz
 */
contract ReputationStaking is ReentrancyGuard {

    using SafeERC20 for IERC20;

    // -------------------------------------------------------------------------
    // Custom errors
    // -------------------------------------------------------------------------

    error ZeroAddressNotAllowed();
    error ZeroAmountNotAllowed();
    error MinimumStakeNotMet(uint256 provided, uint256 minimum);
    error AgentAlreadyListed(address agent);
    error AgentNotListed(address agent);
    error InsufficientStake(uint256 available, uint256 required);
    error CannotWithdrawWhileListed(address agent);
    error SlashExceedsStake(uint256 slashAmount, uint256 stakedAmount);
    error OnlySlashAuthorityCanDoThis(address caller, address authority);
    error OnlyAgentCanDoThis(address caller, address agent);
    error SlashAuthorityAlreadySet();
    error TreasuryAlreadySet();
    error SetupIncomplete();
    error ServicePriceTooLow();
    error InvalidCategory(uint8 category);
    error StakeAmountMustBePositive();

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------

    // The minimum USDC a seller must stake to list a service
    // Set at 100 USDC — enough to deter spam but not prohibitive
    uint256 public constant MINIMUM_STAKE = 100e6;

    // What percentage of a slash goes to the harmed buyer
    // The rest goes to the treasury
    // 70% to buyer, 30% to treasury
    uint256 public constant BUYER_SLASH_SHARE_BPS  = 7000;
    uint256 public constant BASIS_POINTS            = 10000;

    // Service categories — must match ACTION types in PolicyRegistry
    uint8 public constant CATEGORY_DATA_FEED   = 0;
    uint8 public constant CATEGORY_DEX_SWAP    = 1;
    uint8 public constant CATEGORY_LENDING     = 2;
    uint8 public constant CATEGORY_EXECUTION   = 3;
    uint8 public constant CATEGORY_YIELD       = 4;
    uint8 public constant MAX_CATEGORY         = 4;

    // -------------------------------------------------------------------------
    // Types
    // -------------------------------------------------------------------------

    enum ListingStatus { Unlisted, Active, Suspended }

    struct ServiceListing {
        // The agent providing this service
        address agent;

        // Price per call in USDC
        uint256 pricePerCall;

        // Which category this service falls under
        uint8 category;

        // Current listing status
        ListingStatus status;

        // How much USDC this agent has staked
        uint256 stakedAmount;

        // Total calls completed successfully — used for reputation scoring
        uint256 successfulCalls;

        // Total calls that were disputed or failed
        uint256 failedCalls;

        // When this listing was first created
        uint256 listedAt;

        // A short description of what this service does
        bytes32 description;
    }

    // -------------------------------------------------------------------------
    // Storage
    // -------------------------------------------------------------------------

    // The USDC token used for staking
    IERC20 public immutable stakingToken;

    // Where slash proceeds for the protocol go
    address public treasury;
    bool    private treasurySet;

    // The only address that can slash stakes — set to SentinelGate after deploy
    address public slashAuthority;
    bool    private slashAuthoritySet;

    // All service listings indexed by agent address
    mapping(address => ServiceListing) private listings;

    // All agents who have ever listed — for enumeration
    address[] private listedAgents;

    // Tracks whether an address has been added to listedAgents array
    mapping(address => bool) private everListed;

    // Total USDC held in this contract as stakes
    uint256 public totalStaked;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event ServiceListed(
        address indexed agent,
        uint8 category,
        uint256 pricePerCall,
        uint256 stakedAmount
    );

    event ServiceDelisted(
        address indexed agent,
        uint256 stakeReturned
    );

    event StakeIncreased(
        address indexed agent,
        uint256 addedAmount,
        uint256 newTotal
    );

    event StakeSlashed(
        address indexed agent,
        address indexed buyer,
        uint256 slashedAmount,
        uint256 buyerReceived,
        uint256 treasuryReceived
    );

    event ServiceSuspended(
        address indexed agent,
        string  reason
    );

    event ServiceReinstated(
        address indexed agent
    );

    event CallRecorded(
        address indexed agent,
        bool    success
    );

    event SlashAuthoritySet(address indexed authority);
    event TreasurySet(address indexed treasury);

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    constructor(address _stakingToken) {
        if (_stakingToken == address(0)) revert ZeroAddressNotAllowed();
        stakingToken = IERC20(_stakingToken);
    }

    // -------------------------------------------------------------------------
    // One-time setup
    // -------------------------------------------------------------------------

    function setSlashAuthority(address _authority) external {
        if (slashAuthoritySet) revert SlashAuthorityAlreadySet();
        if (_authority == address(0)) revert ZeroAddressNotAllowed();
        slashAuthority = _authority;
        slashAuthoritySet = true;
        emit SlashAuthoritySet(_authority);
    }

    function setTreasury(address _treasury) external {
        if (treasurySet) revert TreasuryAlreadySet();
        if (_treasury == address(0)) revert ZeroAddressNotAllowed();
        treasury = _treasury;
        treasurySet = true;
        emit TreasurySet(_treasury);
    }

    modifier onlySlashAuthority() {
        if (msg.sender != slashAuthority)
            revert OnlySlashAuthorityCanDoThis(msg.sender, slashAuthority);
        _;
    }

    modifier setupComplete() {
        if (!slashAuthoritySet || !treasurySet)
            revert SetupIncomplete();
        _;
    }

    // -------------------------------------------------------------------------
    // Listing management
    // -------------------------------------------------------------------------

    /**
     * @notice List a service on the marketplace by staking USDC.
     * @dev The agent must approve this contract to spend their USDC first.
     *      Stake is locked for as long as the listing is active.
     */
    function listService(
        uint256 stakeAmount,
        uint256 pricePerCall,
        uint8   category,
        bytes32 description
    )
        external
        nonReentrant
        setupComplete
    {
        if (stakeAmount < MINIMUM_STAKE)
            revert MinimumStakeNotMet(stakeAmount, MINIMUM_STAKE);

        if (pricePerCall == 0)
            revert ServicePriceTooLow();

        if (category > MAX_CATEGORY)
            revert InvalidCategory(category);

        if (listings[msg.sender].status == ListingStatus.Active)
            revert AgentAlreadyListed(msg.sender);

        // Pull the stake from the agent
        stakingToken.safeTransferFrom(msg.sender, address(this), stakeAmount);
        totalStaked += stakeAmount;

        listings[msg.sender] = ServiceListing({
            agent:          msg.sender,
            pricePerCall:   pricePerCall,
            category:       category,
            status:         ListingStatus.Active,
            stakedAmount:   stakeAmount,
            successfulCalls: 0,
            failedCalls:    0,
            listedAt:       block.timestamp,
            description:    description
        });

        if (!everListed[msg.sender]) {
            listedAgents.push(msg.sender);
            everListed[msg.sender] = true;
        }

        emit ServiceListed(msg.sender, category, pricePerCall, stakeAmount);
    }

    /**
     * @notice Delist a service and withdraw the full stake.
     * @dev Only the agent themselves can delist. Suspended agents
     *      cannot delist — the slash authority must reinstate first.
     */
    function delistService() external nonReentrant {
        ServiceListing storage listing = listings[msg.sender];

        if (listing.status != ListingStatus.Active)
            revert AgentNotListed(msg.sender);

        uint256 stakeToReturn = listing.stakedAmount;

        // Clear the listing before transferring to prevent reentrancy
        listing.status      = ListingStatus.Unlisted;
        listing.stakedAmount = 0;
        totalStaked -= stakeToReturn;

        stakingToken.safeTransfer(msg.sender, stakeToReturn);

        emit ServiceDelisted(msg.sender, stakeToReturn);
    }

    /**
     * @notice Add more stake to an active listing.
     * @dev More stake signals higher commitment and improves reputation score.
     */
    function increaseStake(uint256 additionalAmount)
        external
        nonReentrant
    {
        if (additionalAmount == 0) revert StakeAmountMustBePositive();

        ServiceListing storage listing = listings[msg.sender];
        if (listing.status != ListingStatus.Active)
            revert AgentNotListed(msg.sender);

        stakingToken.safeTransferFrom(msg.sender, address(this), additionalAmount);
        listing.stakedAmount += additionalAmount;
        totalStaked += additionalAmount;

        emit StakeIncreased(msg.sender, additionalAmount, listing.stakedAmount);
    }

    // -------------------------------------------------------------------------
    // Slash mechanism
    // -------------------------------------------------------------------------

    /**
     * @notice Slash an agent's stake for malicious or failed service.
     * @dev Only the slash authority (SentinelGate) can call this.
     *      70% goes to the harmed buyer, 30% to the protocol treasury.
     *      If the slash amount exceeds the stake, we slash everything.
     *
     * @param agent       The misbehaving agent.
     * @param buyer       Who was harmed — receives 70% of the slash.
     * @param slashAmount How much to slash.
     * @param reason      Why this slash is happening.
     */
    function slashStake(
        address agent,
        address buyer,
        uint256 slashAmount,
        string calldata reason
    )
        external
        nonReentrant
        onlySlashAuthority
    {
        if (agent == address(0)) revert ZeroAddressNotAllowed();
        if (buyer == address(0)) revert ZeroAddressNotAllowed();
        if (slashAmount == 0)    revert ZeroAmountNotAllowed();

        ServiceListing storage listing = listings[agent];

        // We can slash both active and suspended agents
        // but not agents who have never listed
        if (listing.stakedAmount == 0)
            revert InsufficientStake(0, slashAmount);

        // Cap the slash at whatever is staked — never go negative
        uint256 actualSlash = slashAmount > listing.stakedAmount
            ? listing.stakedAmount
            : slashAmount;

        // Calculate the split
        uint256 buyerAmount    = (actualSlash * BUYER_SLASH_SHARE_BPS) / BASIS_POINTS;
        uint256 treasuryAmount = actualSlash - buyerAmount;

        // Update state before transfers
        listing.stakedAmount -= actualSlash;
        listing.status        = ListingStatus.Suspended;
        totalStaked          -= actualSlash;

        // Transfer to buyer
        if (buyerAmount > 0) {
            stakingToken.safeTransfer(buyer, buyerAmount);
        }

        // Transfer to treasury
        if (treasuryAmount > 0) {
            stakingToken.safeTransfer(treasury, treasuryAmount);
        }

        emit StakeSlashed(agent, buyer, actualSlash, buyerAmount, treasuryAmount);
        emit ServiceSuspended(agent, reason);
    }

    // -------------------------------------------------------------------------
    // Call recording — called by SentinelGate after marketplace transactions
    // -------------------------------------------------------------------------

    /**
     * @notice Record the outcome of a service call.
     * @dev Updates the agent's success/failure counters which feed
     *      into the reputation score calculation.
     */
    function recordCall(address agent, bool success)
        external
        onlySlashAuthority
    {
        ServiceListing storage listing = listings[agent];
        if (listing.status == ListingStatus.Unlisted)
            revert AgentNotListed(agent);

        if (success) {
            listing.successfulCalls++;
        } else {
            listing.failedCalls++;
        }

        emit CallRecorded(agent, success);
    }

    /**
     * @notice Reinstate a suspended agent after they have topped up their stake.
     * @dev Only the slash authority can reinstate — prevents self-reinstatement.
     */
    function reinstateService(address agent)
        external
        onlySlashAuthority
    {
        ServiceListing storage listing = listings[agent];
        if (listing.status != ListingStatus.Suspended)
            revert AgentNotListed(agent);
        if (listing.stakedAmount < MINIMUM_STAKE)
            revert MinimumStakeNotMet(listing.stakedAmount, MINIMUM_STAKE);

        listing.status = ListingStatus.Active;
        emit ServiceReinstated(agent);
    }

    // -------------------------------------------------------------------------
    // View functions
    // -------------------------------------------------------------------------

    function getListing(address agent)
        external
        view
        returns (ServiceListing memory)
    {
        return listings[agent];
    }

    function isListed(address agent) external view returns (bool) {
        return listings[agent].status == ListingStatus.Active;
    }

    function getReputationScore(address agent)
        external
        view
        returns (uint8 score)
    {
        ServiceListing storage listing = listings[agent];

        if (listing.status == ListingStatus.Unlisted) return 0;

        uint256 total = listing.successfulCalls + listing.failedCalls;

        if (total == 0) {
            // New listing with no call history
            // Base score determined by stake size relative to minimum
            // More stake = higher base trust, capped at 60
            uint256 stakeMultiple = listing.stakedAmount / MINIMUM_STAKE;
            uint256 baseScore = stakeMultiple * 10;
            return uint8(baseScore > 60 ? 60 : baseScore);
        }

        // Score = (successful / total) * 100, adjusted for stake size
        uint256 successRate = (listing.successfulCalls * 100) / total;

        // Suspended agents take a 20 point penalty
        if (listing.status == ListingStatus.Suspended) {
            successRate = successRate > 20 ? successRate - 20 : 0;
        }

        return uint8(successRate > 100 ? 100 : successRate);
    }

    function getActiveListings()
        external
        view
        returns (address[] memory active)
    {
        uint256 count = 0;
        for (uint256 i = 0; i < listedAgents.length; i++) {
            if (listings[listedAgents[i]].status == ListingStatus.Active) {
                count++;
            }
        }

        active = new address[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < listedAgents.length; i++) {
            if (listings[listedAgents[i]].status == ListingStatus.Active) {
                active[idx++] = listedAgents[i];
            }
        }
    }

    function getTotalListings() external view returns (uint256) {
        return listedAgents.length;
    }
}

src/RiskGuardian.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@pythnetwork/pyth-sdk-solidity/IPyth.sol";
import "@pythnetwork/pyth-sdk-solidity/PythStructs.sol";

/**
 * @title RiskGuardian
 * @author Arbit Protocol
 * @notice The real-time risk scoring engine for Arbit. Before any payment
 *         executes, SentinelGate queries this contract for the current risk
 *         score. If the score exceeds the policy ceiling, the payment is
 *         blocked automatically — no human intervention required.
 *
 * @dev Scoring uses five weighted dimensions.
 *      Price Volatility 25pct, Oracle Confidence 20pct, TVL Stability 25pct,
 *      Contract Security 20pct, Agent Behaviour 10pct.
 *      Score range: 0 (safe) to 100 (extremely dangerous).
 *      Block threshold: configurable per policy in PolicyRegistry.
 *
 * @dev The Pyth oracle is the primary data source. Chainlink is used as a
 *      secondary cross-validation layer. If the two feeds diverge by more
 *      than MAX_DIVERGENCE_BPS, the oracle confidence score spikes — this
 *      is the exact signal that was absent during the February 2026 cascade.
 *
 * @dev Security invariants:
 *      1. Score always returns a value between 0 and 100
 *      2. Oracle divergence always increases the risk score, never decreases it
 *      3. Only the admin can register protocol risk profiles
 *      4. Stale oracle data always produces a high confidence penalty
 *
 * @custom:security-contact security@arbitprotocol.xyz
 */
contract RiskGuardian {

    // -------------------------------------------------------------------------
    // Custom errors
    // -------------------------------------------------------------------------

    error ZeroAddressNotAllowed();
    error OnlyAdminCanDoThis(address caller, address admin);
    error InvalidWeight(uint256 totalWeight);
    error StalenessThresholdTooLow(uint256 provided, uint256 minimum);
    error ProtocolNotRegistered(address protocol);

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------

    // Arbitrum Sepolia Pyth contract address
    address public constant PYTH_ARBITRUM_SEPOLIA =
        0x940d67A2492bf5e39Ce7AaD5E28e14E4e67D01D3;

    // Maximum acceptable divergence between Pyth and Chainlink in basis points
    // If feeds diverge by more than 2%, we treat oracle data as unreliable
    uint256 public constant MAX_DIVERGENCE_BPS = 200;

    // Minimum acceptable oracle data age in seconds
    // Data older than this is treated as stale and penalised
    uint256 public constant MAX_PRICE_AGE = 60;

    // Score weights — must sum to 100
    uint8 public constant WEIGHT_VOLATILITY   = 25;
    uint8 public constant WEIGHT_ORACLE_CONF  = 20;
    uint8 public constant WEIGHT_TVL          = 25;
    uint8 public constant WEIGHT_CONTRACT_SEC = 20;
    uint8 public constant WEIGHT_AGENT_BEHAV  = 10;

    // Penalty applied when oracle data is stale or feeds diverge
    uint8 public constant ORACLE_STALE_PENALTY   = 40;
    uint8 public constant ORACLE_DIVERGE_PENALTY = 30;

    // -------------------------------------------------------------------------
    // Types
    // -------------------------------------------------------------------------

    /**
     * @dev Risk profile for a registered protocol.
     *      Admins register protocols with their known risk parameters.
     *      Unknown protocols get a conservative default score.
     */
    struct ProtocolRiskProfile {
        // Has this protocol been registered by the admin
        bool registered;

        // Pyth price feed ID for this protocol's primary asset
        bytes32 pythPriceFeedId;

        // Chainlink aggregator address for cross-validation
        address chainlinkFeed;

        // Base security score set by admin based on audit status
        // 0 = fully audited, recent, multisig — 100 = unaudited, unknown
        uint8 baseSecurityScore;

        // Unix timestamp of the protocol's last known audit
        uint256 lastAuditTimestamp;

        // Whether this protocol has had a recent exploit or bug report
        bool recentExploit;

        // Admin-set TVL reference point — used to detect rapid outflows
        uint256 referenceTVL;

        // Current TVL — updated by the admin or an authorised reporter
        uint256 currentTVL;
    }

    /**
     * @dev Behaviour profile for a registered agent.
     *      Tracks signals that indicate herding or anomalous activity.
     */
    struct AgentBehaviourProfile {
        // How many times this agent has triggered a risk block
        uint256 riskTriggerCount;

        // Timestamp of the last transaction
        uint256 lastTransactionTime;

        // How many transactions in the last observation window
        uint256 transactionsInWindow;

        // Whether this agent is currently flagged for herding
        bool herdingFlagged;

        // Whether this agent address appears in known malicious address lists
        bool maliciousFlagged;
    }

    // -------------------------------------------------------------------------
    // Storage
    // -------------------------------------------------------------------------

    IPyth public immutable pyth;
    address public admin;

    // Registered protocol risk profiles
    mapping(address => ProtocolRiskProfile) private protocolProfiles;

    // Agent behaviour profiles — updated by SentinelGate after each transaction
    mapping(address => AgentBehaviourProfile) private agentProfiles;

    // The authorised reporter who can update TVL and agent behaviour data
    address public dataReporter;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event ProtocolRegistered(address indexed protocol, uint8 baseSecurityScore);
    event ProtocolTVLUpdated(address indexed protocol, uint256 newTVL);
    event AgentFlagged(address indexed agent, bool herding, bool malicious);
    event AgentRiskTriggerRecorded(address indexed agent, uint256 totalTriggers);
    event AdminTransferred(address indexed previous, address indexed next);
    event DataReporterSet(address indexed reporter);
    event RiskScoreComputed(
        bytes32 indexed policyId,
        address indexed protocol,
        uint8 finalScore,
        uint8 volatilityScore,
        uint8 oracleScore,
        uint8 tvlScore,
        uint8 securityScore,
        uint8 behaviourScore
    );

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    constructor(address _pyth, address _admin) {
        if (_pyth  == address(0)) revert ZeroAddressNotAllowed();
        if (_admin == address(0)) revert ZeroAddressNotAllowed();
        pyth  = IPyth(_pyth);
        admin = _admin;
    }

    // -------------------------------------------------------------------------
    // Access control
    // -------------------------------------------------------------------------

    modifier onlyAdmin() {
        if (msg.sender != admin)
            revert OnlyAdminCanDoThis(msg.sender, admin);
        _;
    }

    modifier onlyReporter() {
        if (msg.sender != dataReporter && msg.sender != admin)
            revert OnlyAdminCanDoThis(msg.sender, dataReporter);
        _;
    }

    // -------------------------------------------------------------------------
    // Admin configuration
    // -------------------------------------------------------------------------

    function setDataReporter(address _reporter) external onlyAdmin {
        if (_reporter == address(0)) revert ZeroAddressNotAllowed();
        dataReporter = _reporter;
        emit DataReporterSet(_reporter);
    }

    function transferAdmin(address newAdmin) external onlyAdmin {
        if (newAdmin == address(0)) revert ZeroAddressNotAllowed();
        address previous = admin;
        admin = newAdmin;
        emit AdminTransferred(previous, newAdmin);
    }

    function registerProtocol(
        address protocol,
        bytes32 pythPriceFeedId,
        address chainlinkFeed,
        uint8   baseSecurityScore,
        uint256 lastAuditTimestamp,
        bool    recentExploit,
        uint256 referenceTVL
    ) external onlyAdmin {
        if (protocol == address(0)) revert ZeroAddressNotAllowed();

        protocolProfiles[protocol] = ProtocolRiskProfile({
            registered:        true,
            pythPriceFeedId:   pythPriceFeedId,
            chainlinkFeed:     chainlinkFeed,
            baseSecurityScore: baseSecurityScore,
            lastAuditTimestamp: lastAuditTimestamp,
            recentExploit:     recentExploit,
            referenceTVL:      referenceTVL,
            currentTVL:        referenceTVL
        });

        emit ProtocolRegistered(protocol, baseSecurityScore);
    }

    function updateProtocolTVL(address protocol, uint256 newTVL)
        external
        onlyReporter
    {
        protocolProfiles[protocol].currentTVL = newTVL;
        emit ProtocolTVLUpdated(protocol, newTVL);
    }

    function updateAgentBehaviour(
        address agent,
        bool    herdingFlagged,
        bool    maliciousFlagged,
        uint256 transactionsInWindow
    ) external onlyReporter {
        AgentBehaviourProfile storage profile = agentProfiles[agent];
        profile.herdingFlagged        = herdingFlagged;
        profile.maliciousFlagged      = maliciousFlagged;
        profile.transactionsInWindow  = transactionsInWindow;
        profile.lastTransactionTime   = block.timestamp;
        emit AgentFlagged(agent, herdingFlagged, maliciousFlagged);
    }

    function recordRiskTrigger(address agent) external onlyReporter {
        agentProfiles[agent].riskTriggerCount++;
        emit AgentRiskTriggerRecorded(
            agent,
            agentProfiles[agent].riskTriggerCount
        );
    }

    // -------------------------------------------------------------------------
    // Core scoring — called by SentinelGate before every payment
    // -------------------------------------------------------------------------

    /**
     * @notice Compute the aggregate risk score for a payment.
     * @dev This is the function SentinelGate calls. It is view-only —
     *      no state changes, no oracle updates. The score reflects the
     *      current state of all five dimensions at this exact moment.
     *
     * @param protocol  The protocol or agent being paid.
     * @return score    Aggregate risk score 0-100. Higher = more dangerous.
     */
    function getScore(bytes32 /* policyId */, address protocol)
        external
        view
        returns (uint8 score)
    {
        // Compute each dimension independently
        uint8 volatilityScore  = _computeVolatilityScore(protocol);
        uint8 oracleScore      = _computeOracleConfidenceScore(protocol);
        uint8 tvlScore         = _computeTVLScore(protocol);
        uint8 securityScore    = _computeSecurityScore(protocol);
        uint8 behaviourScore   = _computeAgentBehaviourScore(protocol);

        // Weighted sum across all five dimensions
        uint256 weighted =
            (uint256(volatilityScore)  * WEIGHT_VOLATILITY)  +
            (uint256(oracleScore)      * WEIGHT_ORACLE_CONF) +
            (uint256(tvlScore)         * WEIGHT_TVL)         +
            (uint256(securityScore)    * WEIGHT_CONTRACT_SEC)+
            (uint256(behaviourScore)   * WEIGHT_AGENT_BEHAV);

        // Divide by 100 to normalise back to 0-100 range
        uint256 finalScore = weighted / 100;

        // Hard cap at 100 — arithmetic should never exceed this but
        // we enforce it explicitly so the invariant is provable
        score = uint8(finalScore > 100 ? 100 : finalScore);
    }

    // -------------------------------------------------------------------------
    // Dimension 1 — Price Volatility (25% weight)
    // -------------------------------------------------------------------------

    /**
     * @dev Measures how much the asset price has moved relative to
     *      its confidence interval. A wide confidence interval relative
     *      to the price signals high uncertainty and volatility.
     *
     *      Score = (confidence / price) * 1000, capped at 100
     *      A confidence interval of 0.1% of price = score of 1
     *      A confidence interval of 10% of price  = score of 100
     */
    function _computeVolatilityScore(address protocol)
        internal
        view
        returns (uint8)
    {
        ProtocolRiskProfile storage profile = protocolProfiles[protocol];

        // Unknown protocols get a conservative mid-range score
        if (!profile.registered || profile.pythPriceFeedId == bytes32(0)) {
            return 50;
        }

        try pyth.getPriceNoOlderThan(profile.pythPriceFeedId, MAX_PRICE_AGE)
            returns (PythStructs.Price memory price)
        {
            if (price.price <= 0) return 80;

            // Confidence as a percentage of price — scaled to 0-100
            uint256 priceAbs = uint256(uint64(price.price));
            uint256 confAbs  = uint256(price.conf);

            if (priceAbs == 0) return 80;

            // conf/price * 1000 gives us basis point sensitivity
            uint256 volatilityBps = (confAbs * 1000) / priceAbs;

            // Map to 0-100: 0 bps = 0, 100 bps (1%) = 100
            return uint8(volatilityBps > 100 ? 100 : volatilityBps);
        } catch {
            // If oracle call fails, treat as maximum volatility
            return 90;
        }
    }

    // -------------------------------------------------------------------------
    // Dimension 2 — Oracle Confidence (20% weight)
    // -------------------------------------------------------------------------

    /**
     * @dev Measures how reliable the oracle data is at this moment.
     *      Stale data, failed calls, or divergence between Pyth and
     *      Chainlink all increase this score.
     *
     *      This is the dimension that catches oracle manipulation —
     *      the exact attack vector that caused the February 2026 cascade.
     */
    function _computeOracleConfidenceScore(address protocol)
        internal
        view
        returns (uint8)
    {
        ProtocolRiskProfile storage profile = protocolProfiles[protocol];

        if (!profile.registered || profile.pythPriceFeedId == bytes32(0)) {
            return 40; // Unknown protocol — moderate confidence penalty
        }

        // Try to get a fresh price — if stale, apply maximum penalty
        try pyth.getPriceNoOlderThan(profile.pythPriceFeedId, MAX_PRICE_AGE)
            returns (PythStructs.Price memory)
        {
            // Price is fresh — check if Chainlink cross-validation is available
            if (profile.chainlinkFeed == address(0)) {
                // No Chainlink feed — moderate confidence, single oracle
                return 20;
            }

            // Chainlink feed is registered — attempt cross-validation
            // We use a low-level staticcall to avoid reverting if the
            // Chainlink feed is unavailable in the test environment
            (bool success, bytes memory data) = profile.chainlinkFeed.staticcall(
                abi.encodeWithSignature("latestAnswer()")
            );

            if (!success || data.length == 0) {
                // Chainlink unavailable — moderate penalty
                return 25;
            }

            // Both feeds available and fresh — low confidence risk
            return 10;

        } catch {
            // Pyth data is stale or unavailable — apply stale penalty
            return ORACLE_STALE_PENALTY;
        }
    }

    // -------------------------------------------------------------------------
    // Dimension 3 — TVL Stability (25% weight)
    // -------------------------------------------------------------------------

    /**
     * @dev Measures whether the protocol's liquidity is draining rapidly.
     *      A TVL drop of more than 20% from the reference point signals
     *      potential bank-run conditions — exactly what precedes a cascade.
     *
     *      Score = ((referenceTVL - currentTVL) / referenceTVL) * 100
     *      20% TVL drop = score of 20
     *      50% TVL drop = score of 50
     *      80% TVL drop = score of 80
     */
    function _computeTVLScore(address protocol)
        internal
        view
        returns (uint8)
    {
        ProtocolRiskProfile storage profile = protocolProfiles[protocol];

        if (!profile.registered) return 30;
        if (profile.referenceTVL == 0) return 30;

        uint256 ref     = profile.referenceTVL;
        uint256 current = profile.currentTVL;

        // TVL has increased or stayed the same — healthy
        if (current >= ref) return 0;

        // Calculate the percentage drop
        uint256 dropBps = ((ref - current) * 100) / ref;

        return uint8(dropBps > 100 ? 100 : dropBps);
    }

    // -------------------------------------------------------------------------
    // Dimension 4 — Contract Security (20% weight)
    // -------------------------------------------------------------------------

    /**
     * @dev Measures the security posture of the target protocol.
     *      Based on audit status, audit recency, and recent exploit history.
     *
     *      A recent exploit immediately returns maximum score.
     *      An unaudited protocol gets a high base score.
     *      An audited protocol's score increases gradually over time.
     */
    function _computeSecurityScore(address protocol)
        internal
        view
        returns (uint8)
    {
        ProtocolRiskProfile storage profile = protocolProfiles[protocol];

        // Unknown protocol — conservative score
        if (!profile.registered) return 60;

        // Recent exploit — maximum security risk
        if (profile.recentExploit) return 100;

        uint8 base = profile.baseSecurityScore;

        // Audit decay — score increases by 1 point for every 90 days
        // since the last audit, capped at 40 additional points
        if (profile.lastAuditTimestamp > 0 && block.timestamp > profile.lastAuditTimestamp) {
            uint256 daysSinceAudit = (block.timestamp - profile.lastAuditTimestamp) / 1 days;
            uint256 decayPoints    = daysSinceAudit / 90;
            uint256 decayed        = uint256(base) + (decayPoints > 40 ? 40 : decayPoints);
            return uint8(decayed > 100 ? 100 : decayed);
        }

        return base;
    }

    // -------------------------------------------------------------------------
    // Dimension 5 — Agent Behaviour (10% weight)
    // -------------------------------------------------------------------------

    /**
     * @dev Measures whether the agent being paid shows signs of
     *      herding, anomalous frequency, or known malicious activity.
     *
     *      This is the dimension that specifically addresses the
     *      multi-agent cascade risk — when many agents herd into the
     *      same exit, each one's behaviour score spikes, which raises
     *      the aggregate score across all of them simultaneously.
     */
    function _computeAgentBehaviourScore(address agent)
        internal
        view
        returns (uint8)
    {
        AgentBehaviourProfile storage profile = agentProfiles[agent];

        // Known malicious address — maximum score immediately
        if (profile.maliciousFlagged) return 100;

        uint8 score = 0;

        // Herding flag adds significant risk
        if (profile.herdingFlagged) score += 50;

        // Each past risk trigger adds 5 points, capped at 30
        uint256 triggerPoints = profile.riskTriggerCount * 5;
        score += uint8(triggerPoints > 30 ? 30 : triggerPoints);

        // High transaction frequency in a short window adds 20 points
        if (profile.transactionsInWindow > 10) score += 20;

        return uint8(score > 100 ? 100 : score);
    }

    // -------------------------------------------------------------------------
    // View functions
    // -------------------------------------------------------------------------

    function getProtocolProfile(address protocol)
        external
        view
        returns (ProtocolRiskProfile memory)
    {
        return protocolProfiles[protocol];
    }

    function getAgentProfile(address agent)
        external
        view
        returns (AgentBehaviourProfile memory)
    {
        return agentProfiles[agent];
    }

    function isProtocolRegistered(address protocol)
        external
        view
        returns (bool)
    {
        return protocolProfiles[protocol].registered;
    }
}

